  WHERE v.id IN (SELECT l.round_id FROM turns t JOIN opc_result_links l ON l.turn_actor_id=t.actor_id AND l.turn_id=t.id
    WHERE t.actor_id=p_actor_id AND t.session_id=s.id AND l.step_id='result'));
END $function$;
